cssRules:
.diff-container {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  background: #090a0f;
  border: 1px solid #1e2230;
  border-radius: 6px;
  overflow: hidden;
}
.diff-line {
  display: flex;
  padding: 3px 10px;
  line-height: 1.5;
}
.diff-line .prefix {
  width: 20px;
  user-select: none;
  font-weight: bold;
}
.diff-line.diff-del {
  background: rgba(239, 68, 68, 0.12);
  color: #fca5a5;
}
.diff-line.diff-add {
  background: rgba(34, 197, 94, 0.12);
  color: #86efac;
}
